import{_ as a,o as e,c as o,ai as r}from"./chunks/framework.scx6l_IK.js";const q=JSON.parse('{"title":"不二","description":"","frontmatter":{},"headers":[],"relativePath":"50-概念资料/dict-不二.md","filePath":"50-概念资料/dict-不二.md","lastUpdated":1778155802000}'),l={name:"50-概念资料/dict-不二.md"};function d(i,t,h,u,n,c){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="不二" tabindex="-1">不二 <a class="header-anchor" href="#不二" aria-label="Permalink to &quot;不二&quot;">​</a></h1><blockquote><p>传统：佛家/通用 | 道家对应：玄同</p></blockquote><h2 id="定义" tabindex="-1">定义 <a class="header-anchor" href="#定义" aria-label="Permalink to &quot;定义&quot;">​</a></h2><p>不二是大乘佛法的核心思想——超越二元对立（善恶、对错、美丑、生死等），看到事物的统一性。了空居士的理解非常实用：不是否定二元，是不被二元所束缚。</p><h2 id="了空居士原话" tabindex="-1">了空居士原话 <a class="header-anchor" href="#了空居士原话" aria-label="Permalink to &quot;了空居士原话&quot;">​</a></h2><blockquote><p>&quot;色不异空，空不异色——物质和空不是两回事，是不二的。&quot;</p></blockquote><blockquote><p>&quot;不生不灭、不垢不净、不增不减——不是中间状态，而是超越了这些对立的概念。&quot;</p></blockquote><blockquote><p>&quot;不二不是说不要分好坏善恶，是说不要被好坏善恶这些概念绑住。该善的善，该恶的恶，心里没有挂碍。&quot;</p></blockquote><h2 id="了空居士的独特诠释" tabindex="-1">了空居士的独特诠释 <a class="header-anchor" href="#了空居士的独特诠释" aria-label="Permalink to &quot;了空居士的独特诠释&quot;">​</a></h2><p>了空居士非常强调：<strong>不二不是什么都不分</strong>。修行不是变成&quot;是非不分&quot;的人，而是<strong>做正确的事但不被&quot;做正确的事&quot;这个念头绑住</strong>。这是他对&quot;不二&quot;最务实的解读。</p><h2 id="日常理解" tabindex="-1">日常理解 <a class="header-anchor" href="#日常理解" aria-label="Permalink to &quot;日常理解&quot;">​</a></h2><table tabindex="0"><thead><tr><th>二元对立</th><th>不二视角</th></tr></thead><tbody><tr><td>成功/失败</td><td>都是一种经历，都是成长</td></tr><tr><td>好人/坏人</td><td>每个人都有善和恶的种子</td></tr><tr><td>快乐/痛苦</td><td>都是生灭的，不永恒</td></tr><tr><td>修行/世俗</td><td>家庭、工作都是道场</td></tr></tbody></table><h2 id="相关概念" tabindex="-1">相关概念 <a class="header-anchor" href="#相关概念" aria-label="Permalink to &quot;相关概念&quot;">​</a></h2><ul><li><a href="/50-概念资料/dict-平常心">平常心</a> — 不二的日常表现</li><li><a href="/50-概念资料/dict-中道">中道</a> — 不二的实践方法</li></ul><h2 id="相关模型" tabindex="-1">相关模型 <a class="header-anchor" href="#相关模型" aria-label="Permalink to &quot;相关模型&quot;">​</a></h2><ul><li><a href="/10-核心模型/model-圆融中和">圆融中和</a> — 不二的处世表现</li></ul><h2 id="修行实践" tabindex="-1">修行实践 <a class="header-anchor" href="#修行实践" aria-label="Permalink to &quot;修行实践&quot;">​</a></h2><ul><li>遇到对立的事物，试着找出它们共同的一面</li><li>不急着站队，先看看整体</li><li>做正确的事，但做完就放下</li></ul>',18)])])}const b=a(l,[["render",d]]);export{q as __pageData,b as default};
